import itertools,sys
from functools import lru_cache
def syt(shape):
    n=sum(shape); res=[]
    def rec(t,k):
        if k>n: res.append([r[:] for r in t]); return
        for i in range(len(shape)):
            if len(t[i])<shape[i] and (i==0 or len(t[i-1])>len(t[i])):
                t[i].append(k); rec(t,k+1); t[i].pop()
    rec([[] for _ in shape],1); return res
def ins(t,x):
    t=[r[:] for r in t]
    for i,r in enumerate(t):
        j=next((j for j,v in enumerate(r) if v>x),None)
        if j is None: r.append(x); return i,len(r)-1
        r[j],x=x,r[j]
    return len(t),0
for A in range(2,5):
  for B in range(2,5):
    if A*B>13: continue
    shape=[A]*(B-1)+[A-1]
    ts=syt(shape); c=0
    for t in ts:
        if any(ins(t,n+0.5)==(B-1,A-1) for n in range(A*B)): c+=1
    print(A,B,len(ts),c)
